=== 1. LE SCHEMA, en JavaScript commente ===

/*
  monde.js  remplace animaux.js.
  UNE structure pour trois types. Ce qui est marque NOUVEAU n'existe pas
  aujourd'hui dans animaux.js. Tout le reste est deja la, au nom pres.
  Charge par <script> classique : file:// interdit les modules ES et interdit
  fetch() sur un .json local. Aucune donnee ne passera jamais par du JSON.
*/
const ENTITE = {
  /* ---- 1. IDENTITE -------------------------------------------------- */
  id: "",          // unique dans TOUT le monde, tous types confondus.
                   // sert de cle de lien, d'ancre URL (#kenya) et de defaut
                   // pour la silhouette.
  type: "",        // NOUVEAU. "animal" | "fruit" | "pays". Trois valeurs,
                   // jamais une quatrieme. Le type ne pilote AUCUNE branche
                   // dans le moteur de reponse, seulement l'affichage et la
                   // regle de veracite (point 4 des regles de chargement).
  nom: "",         // ce qui s'affiche en gros. "Nox", "Mangue", "Kenya".
  categorie: "",   // EX-CHAMP espece. La ligne sous le nom.
                   // animal "Corbeau freux" / fruit "Fruit a noyau" /
                   // pays "Republique d'Afrique de l'Est".

  /* ---- 2. APPARTENANCE ET LIENS -------------------------------------- */
  terrain: "",     // NOUVEAU. id d'un TERRAIN. Obligatoire pour les 3 types.
                   // Un pays appartient au terrain qui le represente a l'ecran
                   // (Kenya -> savane). C'est ce qui remplace la page unique.
  liens: [         // NOUVEAU. Ecrits DANS UN SEUL SENS. L'inverse est calcule
                   // au chargement. Ne jamais ecrire les deux, ils divergeront.
    { vers: "", relation: "", note: "" }
  ],
  // relation, liste FERMEE, toute autre valeur est refusee au chargement :
  //   "pousse_en"  fruit  -> pays     inverse calcule : "abrite"
  //   "vit_en"     animal -> pays     inverse calcule : "abrite"
  //   "voisin_de"  pays   -> pays     symetrique
  //   "cousin_de"  fruit->fruit ou animal->animal   symetrique
  // note : une phrase courte affichee sur le bouton de navigation. Facultatif.

  /* ---- 3. RENDU ------------------------------------------------------ */
  silhouette: "",  // NOUVEAU. Nom de la fonction de dessin. Defaut = id.
                   // Indispensable des qu'il y a 40 fruits : ils partagent
                   // "fruit_rond" ou "fruit_allonge" au lieu d'avoir 40 fonctions.
  couleur: "",     // inchange
  accent: "",      // inchange
  x: 0, y: 0,      // 0..1 mais DESORMAIS relatif au terrain, pas a la page
  taille: 1,       // inchange

  /* ---- 4. VOIX ------------------------------------------------------- */
  voix: {          // NOUVEAU comme bloc. accroche et ouverture y demenagent tels quels.
    accroche: "",  // une ligne au survol. Etait a la racine.
    ouverture: "", // la premiere bulle. Etait a la racine.
    ton: "",       // UNE phrase qui dit comment cette entite parle.
                   // Sert a l'humain qui ecrit les sujets ET au prompt vocal.
    tics: [],      // 2 a 4 tournures propres a l'entite. Passees au prompt vocal.
    ignore: [],    // ce que l'entite ne PEUT PAS savoir. Passees au prompt vocal.
                   // C'est ce champ qui empeche un fruit de citer une date.
    esquives: []   // si vide, on retombe sur ZOO.ESQUIVES global. Inchange sinon.
  },

  /* ---- 5. SUJETS ----------------------------------------------------- */
  sujets: [],      // tableau de SUJET, voir ci-dessous

  /* ---- 6. DEGUSTATION ------------------------------------------------ */
  degustation: null // null sauf type "fruit". Voir DEGUSTATION ci-dessous.
};

=== 2. LE SUJET ET LA SOURCE ===

const SUJET = {
  id: "",        // NOUVEAU, OBLIGATOIRE. C'est la cible de ouvre et de requiert.
                 // Aujourd'hui ouvre:["memoire"] pointe vers une CLE, pas vers
                 // un sujet : ca marche par accident parce que la cle et le nom
                 // du sujet suivant sont le meme mot. Avec 300 entites ca casse.
  cles: [],      // inchange
  reponse: "",   // inchange
  ouvre: [],     // inchange dans sa forme. NOUVEAU dans sa portee : un id sans
                 // ":" est local a l'entite, un id avec ":" ouvre un sujet chez
                 // une AUTRE entite. "kenya:independance". C'est ce qui fait
                 // qu'un fruit peut debloquer un chapitre d'un pays.
  requiert: [],  // deja lu par moteur.js ligne 60, jamais rempli aujourd'hui.
                 // Donc les couches annoncees dans le commentaire d'animaux.js
                 // n'existent pas encore. Meme syntaxe locale ou "entite:sujet".
  sources: [],   // NOUVEAU, OBLIGATOIRE, au moins une entree. Voir SOURCE.
  publie: true   // CALCULE au chargement, jamais ecrit a la main.
};

const SOURCE = {
  type: "",     // "fiction" | "reference" | "non_verifie"
  extrait: "",  // les mots EXACTS pris dans reponse que cette source couvre.
                // "*" = toute la reponse. verifier() controle que
                // reponse.includes(extrait), sinon le sujet est refuse : ca
                // empeche une source de rester accrochee a une phrase reecrite.
  ref: "",      // "Auteur, titre, page" ou "Institution, tableau X". type reference.
  url: "",
  consulte: ""  // "AAAA-MM-JJ"
};

=== 3. LA DEGUSTATION (type fruit uniquement) ===

const DEGUSTATION = {
  verbe: "Croquer",   // libelle du bouton
  etapes: [           // jouees dans l'ordre, dans le fil de dialogue existant,
                      // en bulles "animal". Aucune nouvelle zone d'interface.
    { attente: 0,    texte: "" },
    { attente: 1100, texte: "" }
  ],
  profil: {           // 0 a 5. CE SONT DES FAITS. null tant qu'aucune source.
    sucre: null, acide: null, amer: null, astringent: null,
    jus: null, texture: "", odeur: ""
  },
  profilSources: [],  // tableau de SOURCE. Meme regle : un profil sans source
                      // de type reference n'est pas affiche, le bloc gout est
                      // simplement absent, le reste du fruit reste jouable.
  reactions: [        // les "randoms" demandes par MZ. Personnages FIXES et
                      // ecrits, jamais generes. L'interface les annonce comme
                      // fictifs, sinon c'est un faux temoignage.
    { qui: "", texte: "" }
  ],
  tirage: 2,          // combien de reactions affichees par degustation
  graine: 0           // CALCULE : hash de l'id du fruit + numero de degustation.
                      // Tirage reproductible : une demo rejoue la meme scene.
};

Regle d'interface non negociable : le bloc reactions porte un intitule du genre
"Trois visiteurs, personnages fictifs". Le profil de gout, lui, porte sa source.
Les deux ne se melangent pas dans la meme bulle.

