      ouvre: [], requiert: ["memoire"],
      sources: [{ type: "fiction", extrait: "*" }] }

    // Les sujets "outil" et "cage" d'animaux.js migrent a l'identique :
    // ajouter id, requiert:[] et sources:[{type:"fiction",extrait:"*"}].
