LE CONTRAT UNIQUE. window.ZOO.repondre(etat, question) renvoie desormais une Promise d'objet et non plus une chaine :
{ texte: string, source: "predefini" | "vocal", degrade: boolean, note: string|null }
degrade vaut true quand la reponse vient du predefini alors que le mode vocal etait demande. note porte la raison lisible ("agent injoignable", "plafond atteint", "jeton refuse"). Un seul appelant a corriger, index.html:342 :
const r = await Z.repondre(etat, q);
bulle("animal", r.texte, r);
et bulle(qui, texte, meta) ajoute, si meta && (meta.degrade || meta.source === "vocal"), un petit <span class="etiquette"> sous la bulle : "repli hors ligne" en degrade, "vocal, non verifie" en vocal reussi. Le predefini n'affiche rien.

MOTEUR.JS, refactor exact. Supprimer VOCAL_ACTIF, URL_AGENT et demanderALAgent (lignes 17, 18, 116 a 149) : tout ce bloc part dans vocal.js. Extraire le corps du else de repondre() dans une fonction repondrePredefini(etat, question) qui renvoie { texte, source: "predefini", degrade: false, note: null }. Puis un registre :
const MODES = { predefini: { id: "predefini", libelle: "Predefini", repondre: repondrePredefini } };
let modeCourant = "predefini";
function enregistrerMode(m) { MODES[m.id] = m; }
async function definirMode(id) { if (!MODES[id]) return false; modeCourant = id; return true; }
async function repondre(etat, question) {
  const cible = etat.cible; if (!cible) return { texte: "Approchez-vous d'abord.", source: "predefini", degrade: false, note: null };
  etat.historique.push({ qui: "visiteur", texte: question });
  let r;
  try { r = await MODES[modeCourant].repondre(etat, question); }
  catch (e) { r = repondrePredefini(etat, question); r.degrade = true; r.note = String(e.message || e); }
  etat.historique.push({ qui: "animal", texte: r.texte });
  return r;
}
Exporter enregistrerMode, definirMode, modeActuel: () => modeCourant, repondrePredefini. Le mode predefini reste synchrone a l'interieur, la Promise est portee par repondre().

VOCAL.JS, le fichier qui n'est jamais publie. Il s'auto-enregistre, il cree lui-meme sa pastille, il ne touche pas a index.html.

(function () {
"use strict";
const Z = window.ZOO;
if (!Z || typeof Z.enregistrerMode !== "function") return;
const LOCAL = ["127.0.0.1", "localhost", "[::1]"];
if (location.protocol !== "file:" && !LOCAL.includes(location.hostname)) return;  // couche 2
const BASE = "http://127.0.0.1:7860";
const JETON = localStorage.getItem("zoo_jeton") || "";   // seulement le jeton, JAMAIS l'activation
let echecs = 0;

function avecDelai(url, opts, ms) {
  const c = new AbortController();
  const id = setTimeout(() => c.abort(), ms);
  return fetch(url, Object.assign({}, opts, { signal: c.signal })).finally(() => clearTimeout(id));
}
async function sante() {
  const r = await avecDelai(BASE + "/sante", { method: "GET" }, 1500);
  if (!r.ok) throw new Error("pont: " + r.status);
  return r.json();
}
async function appel(etat, question) {
  const c = etat.cible;
  const corps = {
    systeme: [
      "Tu es " + c.nom + ", " + (c.espece || c.type) + ".",
      "Tu parles a la premiere personne, tu ne dis jamais que tu es une IA.",
      "Tu ne peux utiliser QUE les faits fournis ci-dessous.",
      "Si la reponse n'y est pas, tu dis que tu ne sais pas. Tu n'inventes aucune date, aucun chiffre, aucun evenement.",
      "Trois phrases maximum."
    ].join(" "),
    faits: (c.sujets || []).map(s => s.reponse),
    historique: etat.historique.slice(-6),
    question: question
  };
  const r = await avecDelai(BASE + "/parler", {
    method: "POST",
    headers: Object.assign({ "Content-Type": "application/json" }, JETON ? { "X-Zoo-Jeton": JETON } : {}),
    body: JSON.stringify(corps)
  }, 8000);
  if (r.status === 401) throw Object.assign(new Error("jeton refuse"), { fatal: true });
  if (r.status === 429) throw Object.assign(new Error("plafond atteint"), { fatal: true });
  if (!r.ok) throw new Error("pont: " + r.status);
  const j = await r.json();
  if (!j.texte) throw new Error("reponse vide");
  return j;
}
Z.enregistrerMode({ id: "vocal", libelle: "Vocal", sante, repondre: async (etat, question) => { ... } });
})();

